import{_ as s,o as a,c as e,a3 as t}from"./chunks/framework.Dq9u6otn.js";const c=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/faq.md","filePath":"advanced/faq.md"}'),n={name:"advanced/faq.md"};function l(h,i,p,o,d,r){return a(),e("div",null,[...i[0]||(i[0]=[t(`<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><p>这里收集的是实际项目里最常遇到的几类问题。两个版本表现基本一致，涉及写法差异的地方会分别说明。</p><h2 id="下拉刷新没有弹性回弹感" tabindex="-1">下拉刷新没有弹性回弹感 <a class="header-anchor" href="#下拉刷新没有弹性回弹感" aria-label="Permalink to &quot;下拉刷新没有弹性回弹感&quot;">​</a></h2><p><strong>现象</strong>：下拉时很快到底、松手只回弹一次，手感发硬；而示例里「下拉刷新 - 原生效果」那种&quot;松手先回落、刷新完再整体回弹&quot;的两段回弹没有出现。</p><p><strong>原因</strong>：组件下拉时的位移是 <code>moveY = -moveHeight + distance * 0.5</code>，<code>moveHeight</code> 取自 <code>background.height || height</code>。没有设置 <code>background.height</code> 时它等于 <code>height</code>（比如 50），手指拉约 100px 就饱和，只剩单段回弹。</p><p><strong>解决</strong>：让下拉行程大于刷新自身高度：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  height</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,                                  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 刷新自身高度：松手后回落到这里显示加载动画</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  background</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;#f2f2f2&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">height</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">120</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 下拉行程：整体回弹的距离</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>两个版本都适用（uni-app 版写在 <code>&lt;coolui-scroller-refresh :config=&quot;...&quot;&gt;</code> 或对应组件配置里）。</p><h2 id="h5-上出现页面级滚动条-小程序正常" tabindex="-1">H5 上出现页面级滚动条（小程序正常） <a class="header-anchor" href="#h5-上出现页面级滚动条-小程序正常" aria-label="Permalink to &quot;H5 上出现页面级滚动条（小程序正常）&quot;">​</a></h2><p><strong>原因</strong>：H5 端 uni-app 会额外渲染内置导航栏（高度 = <code>--window-top</code>），而页面写的 <code>height: 100vh</code> 是整个视口高度，没扣掉这一截；同时 <code>pages.json</code> 的 <code>disableScroll</code> 只在小程序端生效。所以小程序正常、H5 多出一条滚动条。</p><p><strong>解决</strong>：全屏页按可视区高度兜底，并用条件编译只影响 H5：</p><div class="language-scss vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scss</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* #ifdef H5 */</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.page</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  height</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">calc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">vh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">--window-top</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">px</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">--window-bottom</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">px</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* #endif */</span></span></code></pre></div><p>内容高于一屏的页面（<code>min-height: 100vh</code>）只改 <code>min-height</code> 即可，仍保留正常滚动。详见<a href="/coolui-scroller/v4/uniapp/platform-diff.html#h5-内置导航栏会额外占高">跨端差异</a>。</p><h2 id="列表项之间没有间距、内容贴着卡片边缘" tabindex="-1">列表项之间没有间距、内容贴着卡片边缘 <a class="header-anchor" href="#列表项之间没有间距、内容贴着卡片边缘" aria-label="Permalink to &quot;列表项之间没有间距、内容贴着卡片边缘&quot;">​</a></h2><p><strong>原因</strong>：一是页面里把卡片容器的内边距重置成了 0（<code>.pannel .pannel-inner { padding: 0 }</code>）；二是列表项的间距写成了 <code>.coolui-scroller .item</code> 这类<strong>跨组件选择器</strong>，在页面 scoped 样式里穿不进组件，小程序端尤其明显。</p><p><strong>解决</strong>：</p><ul><li>卡片留白交给容器样式（不要重复声明或重置全局卡片样式）；</li><li>列表项间距写在<strong>页面可命中的选择器</strong>上，或给插槽内容自带 class 后再写样式。</li></ul><h2 id="长列表高度不对-滚动位置跳动" tabindex="-1">长列表高度不对 / 滚动位置跳动 <a class="header-anchor" href="#长列表高度不对-滚动位置跳动" aria-label="Permalink to &quot;长列表高度不对 / 滚动位置跳动&quot;">​</a></h2><p>长列表靠&quot;页&quot;来占位，页高需要算准：</p><ul><li>原生微信小程序版 <code>scroll-page</code>：需要引入组件提供的方法计算每个 page 页面的高度（见 <a href="/coolui-scroller/v4/native/components/page.html">ScrollPage 文档</a>）。</li><li>uni-app 版优先用 <code>coolui-scroller-longlist</code>：窗口化方案，窗口外折叠为上下占位块，不依赖总页数。</li></ul><p>页高与实际内容高度差别越大，滚动条长度和滚动位置就越不准，尽量让每页内容高度一致。</p><h2 id="easycom-配置后组件不生效-uni-app" tabindex="-1">easycom 配置后组件不生效（uni-app） <a class="header-anchor" href="#easycom-配置后组件不生效-uni-app" aria-label="Permalink to &quot;easycom 配置后组件不生效（uni-app）&quot;">​</a></h2><p>按顺序排查：</p><ol><li><code>pages.json</code> 改完是否重新编译；</li><li><code>autoscan: false</code> 时规则必须自己写全，标签名要能匹配你写的正则；</li><li>组件目录名与规则里的路径是否一致（拷贝源码接入时尤其容易漏，路径要指向你实际放置的目录）。</li></ol><p>见<a href="/coolui-scroller/v4/uniapp/install.html#方式一easycom推荐">安装与引入</a>。</p><h2 id="事件-属性名对不上-uni-app" tabindex="-1">事件 / 属性名对不上（uni-app） <a class="header-anchor" href="#事件-属性名对不上-uni-app" aria-label="Permalink to &quot;事件 / 属性名对不上（uni-app）&quot;">​</a></h2><p>原生微信小程序版的 <code>bind:refresh</code> 在 uni-app 版是 <code>@refresh</code>；<code>sort-item</code> 的选中值通过 <code>@update:value</code> 同步；search 组件的 <code>key</code> 因是 Vue 保留字改名为 <code>keyword</code>（<code>@update:keyword</code>）。完整对照见<a href="/coolui-scroller/v4/uniapp/platform-diff.html">与原生微信小程序版的差异</a>。</p><h2 id="该选原生微信小程序版还是-uni-app-版" tabindex="-1">该选原生微信小程序版还是 uni-app 版？ <a class="header-anchor" href="#该选原生微信小程序版还是-uni-app-版" aria-label="Permalink to &quot;该选原生微信小程序版还是 uni-app 版？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的项目</th><th>选它</th></tr></thead><tbody><tr><td>微信小程序原生项目（不走 uni-app 编译）</td><td><a href="/coolui-scroller/v4/native/install.html">原生微信小程序版</a>，包名 <code>coolui-scroller</code></td></tr><tr><td>uni-app 项目，需要同时编译到小程序 / H5 / App</td><td><a href="/coolui-scroller/v4/uniapp/install.html">uni-app 版</a>，包名 <code>coolui-scroller-uni</code></td></tr></tbody></table><p>两个版本组件能力与配置项一致，用顶部平台切换器即可在对应文档间跳转。</p>`,30)])])}const g=s(n,[["render",l]]);export{c as __pageData,g as default};
